import mujoco, numpy as np, time
base = open('model_ref.xml').read()
FULL = mujoco.mjtState.mjSTATE_FULLPHYSICS

def mk(opt):
    return base.replace('<size memory="2M"/>','<size memory="2M"/><option '+opt+'/>')

def sim(model, seed):
    d = mujoco.MjData(model)
    rng = np.random.default_rng(seed)
    d.qpos += rng.normal(0,0.01,size=d.qpos.shape)
    mujoco.mj_forward(model,d)
    for _ in range(int(2.0/model.opt.timestep)): mujoco.mj_step(model,d)
    s=np.zeros(mujoco.mj_stateSize(model,FULL)); mujoco.mj_getState(model,d,s,FULL); return s

ref = mujoco.MjModel.from_xml_string(base)
variants = {
 'PGS def': mk('solver="PGS"'),
 'PGS tol1e-12': mk('solver="PGS" tolerance="1e-12"'),
 'PGS it=100 tol1e-10': mk('solver="PGS" iterations="100" tolerance="1e-10"'),
}
models = {k: mujoco.MjModel.from_xml_string(v) for k,v in variants.items()}
maxerr = {k:0.0 for k in variants}; nfail={k:0 for k in variants}
NSEED=120
t0=time.time()
for seed in range(NSEED):
    r = sim(ref, seed)
    if not np.isfinite(r).all(): print("ref nonfinite at", seed)
    for k,m in models.items():
        s = sim(m, seed)
        assert np.isfinite(s).all(), (k, seed, "NaN/Inf")
        e = np.abs(s-r).max()
        maxerr[k]=max(maxerr[k], e)
        if not np.allclose(s, r, atol=1e-5): nfail[k]+=1
    if seed%20==0: print(seed, {k:f"{v:.2e}" for k,v in maxerr.items()}, f"{time.time()-t0:.1f}s")
print("---- over", NSEED, "seeds ----")
for k in variants: print(f"{k:22s} maxerr {maxerr[k]:.3e} fails {nfail[k]}")
